    maxOperations = math.max(1, tonumber(maxOperations) or 64)
    maxMilliseconds = math.max(0, tonumber(maxMilliseconds) or 1)
    local clock = self.request.clock
    local started = clock and clock()
    -- Only one stage runs per slice. Stage transitions create constant-size
    -- jobs; copying graphs and preparing route rows belong to resumable stages.
    local remaining = maxMilliseconds
    if started then
        -- Leave ten percent for returning from the provider and creating the
        -- next constant-size job. The reported timing includes that overhead.
        remaining = math.max(0, maxMilliseconds * 0.9 - (clock() - started))
    end
    if remaining > 0 then self:AdvancePhase(maxOperations, remaining) end
    self.slices = self.slices + 1
    if started then
        local finished = clock()
        self.startedAt = self.startedAt or started
        self.elapsedMilliseconds = math.max(0, finished - self.startedAt)
        self.lastSliceMilliseconds = math.max(0, finished - started)
        self.totalSliceMilliseconds = (self.totalSliceMilliseconds or 0) + self.lastSliceMilliseconds
        self.maxSliceMilliseconds = math.max(self.maxSliceMilliseconds, self.lastSliceMilliseconds)
    end
